-- green_hive_migration: 0026
-- checkpoint: GH-0604
-- description: Create tenant-safe in-app job-completion notifications with owner-only read acknowledgement.
-- rollback_strategy: FORWARD_FIX_OR_VERIFIED_NOTIFICATION_EXPORT_RESTORE
-- Notifications are generated by the trusted job lifecycle; authenticated clients never choose a recipient or event payload.

CREATE TABLE hive.notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL,
  app_id uuid NOT NULL,
  project_id uuid NOT NULL,
  recipient_user_id uuid NOT NULL,
  job_id uuid NOT NULL UNIQUE,
  event_type text NOT NULL,
  title text NOT NULL,
  body text NOT NULL,
  status text NOT NULL DEFAULT 'UNREAD',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT statement_timestamp(),
  read_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT statement_timestamp(),
  CONSTRAINT notifications_project_scope_fk
    FOREIGN KEY (project_id, app_id, organization_id, recipient_user_id)
    REFERENCES hive.projects(id, app_id, organization_id, owner_user_id)
    ON DELETE RESTRICT,
  CONSTRAINT notifications_job_scope_fk
    FOREIGN KEY (job_id, project_id, app_id, organization_id, recipient_user_id)
    REFERENCES hive.jobs(id, project_id, app_id, organization_id, owner_user_id)
    ON DELETE RESTRICT,
  CONSTRAINT notifications_event_type_check CHECK (event_type = 'JOB_COMPLETED'),
  CONSTRAINT notifications_title_check CHECK (
    char_length(title) BETWEEN 1 AND 160 AND title = pg_catalog.btrim(title)
    AND title !~ '[[:cntrl:]]'
  ),
  CONSTRAINT notifications_body_check CHECK (
    char_length(body) BETWEEN 1 AND 500 AND body = pg_catalog.btrim(body)
    AND body !~ '[[:cntrl:]]'
  ),
  CONSTRAINT notifications_status_check CHECK (status IN ('UNREAD', 'READ')),
  CONSTRAINT notifications_metadata_object_check CHECK (jsonb_typeof(metadata) = 'object'),
  CONSTRAINT notifications_read_lifecycle_check CHECK (
    (status = 'UNREAD' AND read_at IS NULL) OR (status = 'READ' AND read_at IS NOT NULL)
  )
);

CREATE INDEX notifications_recipient_scope_created_idx
  ON hive.notifications (
    organization_id, app_id, recipient_user_id, status, created_at DESC, id DESC
  );

CREATE FUNCTION hive.record_job_completion_notification()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NEW.status = 'COMPLETED' AND OLD.status IS DISTINCT FROM 'COMPLETED' THEN
    INSERT INTO hive.notifications (
      organization_id, app_id, project_id, recipient_user_id, job_id,
      event_type, title, body, metadata
    ) VALUES (
      NEW.organization_id, NEW.app_id, NEW.project_id, NEW.owner_user_id, NEW.id,
      'JOB_COMPLETED', 'Processamento concluído',
      'Uma tarefa do seu projeto foi concluída.',
      jsonb_build_object('jobType', NEW.job_type)
    ) ON CONFLICT (job_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER jobs_record_completion_notification
AFTER UPDATE OF status ON hive.jobs
FOR EACH ROW EXECUTE FUNCTION hive.record_job_completion_notification();

ALTER TABLE hive.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE hive.notifications FORCE ROW LEVEL SECURITY;

CREATE POLICY notifications_owner_or_admin_select ON hive.notifications
  FOR SELECT
  USING (
    hive.is_platform_admin() OR (
      recipient_user_id = auth.uid()
      AND app_id = hive.current_app_id()
      AND organization_id = hive.current_organization_id()
      AND hive.has_trusted_organization_context()
    )
  );

CREATE POLICY notifications_owner_mark_read ON hive.notifications
  FOR UPDATE
  USING (
    recipient_user_id = auth.uid()
    AND app_id = hive.current_app_id()
    AND organization_id = hive.current_organization_id()
    AND hive.has_trusted_organization_context()
  )
  WITH CHECK (
    recipient_user_id = auth.uid()
    AND app_id = hive.current_app_id()
    AND organization_id = hive.current_organization_id()
    AND hive.has_trusted_organization_context()
    AND status = 'READ'
    AND read_at IS NOT NULL
  );

REVOKE ALL ON TABLE hive.notifications FROM PUBLIC;
REVOKE ALL ON FUNCTION hive.record_job_completion_notification() FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    GRANT SELECT, UPDATE (status, read_at, updated_at) ON hive.notifications TO authenticated;
  END IF;
END $$;
